//! Exact key-event fixtures generated by the pinned TypeScript reference.

use std::error::Error;

use keri_cesr::crypto::digest::Digest;
use keri_cesr::crypto::verifier::VerificationKey;
use keri_protocol::event::inception::InceptionBuilder;
use keri_protocol::event::interaction::InteractionBuilder;
use keri_protocol::event::rotation::{RotationBuilder, RotationKind};
use keri_protocol::event::witness::{AmpleMode, ample};
use keri_protocol::event::{ConfigurationTrait, EventError, KeyEvent, ThresholdEncoding};
use keri_protocol::prefix::{IdentifierPrefix, PrefixDerivation};
use keri_protocol::serialization::{Sad, SadValue};
use keri_protocol::threshold::{RationalWeight, SigningThreshold};
use serde::Deserialize;

const REFERENCE_SHA: &str = "91a04a5edd804425f42be75ffbf034f8d14e5cb2";

#[derive(Debug, Deserialize)]
struct Fixture {
    schema_version: u8,
    upstream: String,
    reference_sha: String,
    generated_on: String,
    sources: Vec<String>,
    keys: FixtureKeys,
    cases: Vec<EventCase>,
    ample_table: Vec<AmpleRow>,
    ample_explicit: Vec<AmpleExplicitRow>,
    rejected_cases: Vec<RejectedCase>,
    reference_quirks: ReferenceQuirks,
}

#[derive(Debug, Deserialize)]
struct FixtureKeys {
    transferable: String,
    non_transferable: String,
    second: String,
    next_digest: String,
    multisig: Vec<String>,
    next_digests: Vec<String>,
    witnesses: Vec<String>,
}

#[derive(Debug, Deserialize)]
struct EventCase {
    name: String,
    event_kind: String,
    identifier: String,
    said: String,
    sequence_number: String,
    version_string: String,
    raw: String,
    raw_hex: String,
    raw_byte_size: usize,
}

#[derive(Debug, Deserialize)]
struct AmpleRow {
    witnesses: u32,
    weak: u32,
    strong: u32,
}

#[derive(Debug, Deserialize)]
struct AmpleExplicitRow {
    witnesses: u32,
    faults: u32,
    weak: u32,
    strong: u32,
}

#[derive(Debug, Deserialize)]
struct RejectedCase {
    name: String,
    reference_error_category: String,
    reference_error_message: String,
    rust_error_category: String,
}

#[derive(Debug, Deserialize)]
struct ReferenceQuirks {
    multi_key_inception_needs_an_explicit_code: MultiKeyQuirk,
    next_threshold_encoding_follows_the_current_threshold: NextEncodingQuirk,
    numeric_current_weighted_next_drops_the_field: DroppedFieldQuirk,
    next_threshold_validated_against_the_current_key_count: NextValidationQuirk,
    auto_selected_basic_prefix_skips_its_own_checks: AutoPrefixQuirk,
    rotation_cannot_abandon_an_identifier: AbandonQuirk,
    rotation_ignores_the_configuration_argument: ConfigurationQuirk,
    rotation_omits_absent_identifier_and_prior: OmittedFieldQuirk,
}

#[derive(Debug, Deserialize)]
struct MultiKeyQuirk {
    reference_error_category: String,
    reference_error_message: String,
    note: String,
    rust_decision: String,
    rust_equivalent_case: String,
}

#[derive(Debug, Deserialize)]
struct NextEncodingQuirk {
    weighted_current_numeric_next_integer_encoding: WeightedCurrentCase,
    note: String,
    rust_decision: String,
}

#[derive(Debug, Deserialize)]
struct WeightedCurrentCase {
    raw: String,
    nt: String,
    nt_type: String,
}

#[derive(Debug, Deserialize)]
struct DroppedFieldQuirk {
    raw: String,
    contains_next_threshold: bool,
    note: String,
    rust_error_category: String,
}

#[derive(Debug, Deserialize)]
struct NextValidationQuirk {
    reference_error_message: String,
    note: String,
    rust_decision: String,
    unsatisfiable_accepted: UnsatisfiableCase,
    unsatisfiable_note: String,
}

#[derive(Debug, Deserialize)]
struct UnsatisfiableCase {
    raw: String,
    nt: String,
}

#[derive(Debug, Deserialize)]
struct AutoPrefixQuirk {
    non_transferable_with_next_keys: String,
    non_transferable_with_anchors: String,
    note: String,
    rust_decision: String,
    rust_error_category: String,
}

#[derive(Debug, Deserialize)]
struct AbandonQuirk {
    default_next_threshold: RejectedCase,
    explicit_zero: RejectedCase,
    note: String,
    rust_decision: String,
}

#[derive(Debug, Deserialize)]
struct ConfigurationQuirk {
    fields: String,
    note: String,
    rust_decision: String,
}

#[derive(Debug, Deserialize)]
struct OmittedFieldQuirk {
    missing_identifier: String,
    missing_prior: String,
    note: String,
    rust_decision: String,
}

fn fixture() -> Result<Fixture, Box<dyn Error>> {
    Ok(serde_json::from_str(include_str!(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/fixtures/eventing/v1.json"
    )))?)
}

fn decode_hex(input: &str) -> Result<Vec<u8>, Box<dyn Error>> {
    if !input.len().is_multiple_of(2) {
        return Err("odd-length hexadecimal fixture field".into());
    }
    (0..input.len())
        .step_by(2)
        .map(|index| {
            input
                .get(index..index + 2)
                .ok_or_else(|| Box::<dyn Error>::from("hexadecimal fixture slice out of range"))
                .and_then(|pair| u8::from_str_radix(pair, 16).map_err(Into::into))
        })
        .collect()
}

fn keys(qb64: &[String]) -> Result<Vec<VerificationKey>, Box<dyn Error>> {
    qb64.iter()
        .map(|entry| VerificationKey::from_qb64(entry).map_err(Into::into))
        .collect()
}

fn digests(qb64: &[String]) -> Result<Vec<Digest>, Box<dyn Error>> {
    qb64.iter()
        .map(|entry| Digest::from_qb64(entry).map_err(Into::into))
        .collect()
}

fn prefixes(qb64: &[String]) -> Result<Vec<IdentifierPrefix>, Box<dyn Error>> {
    qb64.iter()
        .map(|entry| IdentifierPrefix::from_qb64(entry).map_err(Into::into))
        .collect()
}

fn weights(entries: &[&str]) -> Result<Vec<RationalWeight>, Box<dyn Error>> {
    entries
        .iter()
        .map(|entry| RationalWeight::parse(entry).map_err(Into::into))
        .collect()
}

fn seal(fields: &[(&str, &str)]) -> Result<Sad, Box<dyn Error>> {
    let mut sad = Sad::new();
    for (label, value) in fields {
        sad.insert((*label).to_owned(), SadValue::text(*value))?;
    }
    Ok(sad)
}

fn event_error_category(error: &EventError) -> &'static str {
    match error {
        EventError::SequenceNumberTooSmall => "SequenceNumberTooSmall",
        EventError::SigningThresholdIsZero => "SigningThresholdIsZero",
        EventError::SigningThresholdExceedsKeys { .. } => "SigningThresholdExceedsKeys",
        EventError::NextThresholdExceedsDigests { .. } => "NextThresholdExceedsDigests",
        EventError::ThresholdTooLarge { .. } => "ThresholdTooLarge",
        EventError::UnrepresentableNextThreshold => "UnrepresentableNextThreshold",
        EventError::DuplicateWitness { .. } => "DuplicateWitness",
        EventError::ConflictingWitnessLists { .. } => "ConflictingWitnessLists",
        EventError::WitnessCutNotPresent => "WitnessCutNotPresent",
        EventError::InvalidWitnessThreshold { .. } => "InvalidWitnessThreshold",
        EventError::FaultToleranceTooHigh { .. } => "FaultToleranceTooHigh",
        EventError::DelegatedPrefixMustBeDigestive { .. } => "DelegatedPrefixMustBeDigestive",
        EventError::ValueOutOfRange { .. } => "ValueOutOfRange",
        EventError::Prefix { .. } => "Prefix",
        EventError::Said { .. } => "Said",
        EventError::Sad { .. } => "Sad",
        EventError::Serialization { .. } => "Serialization",
        EventError::Crypto { .. } => "Crypto",
        _ => "Unknown",
    }
}

/// Rebuilds every fixture case through the Rust builders, keyed by case name.
#[expect(
    clippy::too_many_lines,
    reason = "one arm per fixture case; splitting the table would separate each case from the \
              fixture entry it reproduces and make a missing case harder to spot"
)]
fn build_case(name: &str, fixture: &Fixture) -> Result<Option<KeyEvent>, Box<dyn Error>> {
    let transferable = VerificationKey::from_qb64(&fixture.keys.transferable)?;
    let non_transferable = VerificationKey::from_qb64(&fixture.keys.non_transferable)?;
    let second = VerificationKey::from_qb64(&fixture.keys.second)?;
    let next_digest = Digest::from_qb64(&fixture.keys.next_digest)?;
    let multisig = keys(&fixture.keys.multisig)?;
    let next_digests = digests(&fixture.keys.next_digests)?;
    let witnesses = prefixes(&fixture.keys.witnesses)?;

    // The rotations and interactions all follow this identifier.
    let root = InceptionBuilder::new(vec![transferable.clone()])
        .next_key_digests(vec![next_digest])
        .prefix_derivation(PrefixDerivation::Blake3_256)
        .build()?;
    let root_identifier_qb64 = root.identifier().qb64()?;
    let root_said_qb64 = root.said().qb64()?;
    let rotation = || {
        RotationBuilder::new(root.identifier().clone(), root.said(), 1, vec![second.clone()])
            .next_key_digests(vec![next_digest])
            .signing_threshold(SigningThreshold::numeric(1))
            .next_threshold(SigningThreshold::numeric(1))
    };

    let event = match name {
        "pinned_non_transferable_inception" => InceptionBuilder::new(vec![non_transferable]).build()?,
        "pinned_transferable_inception" => InceptionBuilder::new(vec![transferable]).build()?,
        "pinned_self_addressing_inception_text" => root,
        "pinned_self_addressing_inception_integer" => InceptionBuilder::new(vec![transferable])
            .next_key_digests(vec![next_digest])
            .prefix_derivation(PrefixDerivation::Blake3_256)
            .threshold_encoding(ThresholdEncoding::Integer)
            .build()?,
        "multisig_inception" => InceptionBuilder::new(multisig)
            .signing_threshold(SigningThreshold::numeric(2))
            .next_key_digests(next_digests)
            .next_threshold(SigningThreshold::numeric(1))
            .prefix_derivation(PrefixDerivation::Blake3_256)
            .build()?,
        "weighted_inception" => InceptionBuilder::new(multisig)
            .signing_threshold(SigningThreshold::weighted(vec![weights(&["1/2", "1/2", "1/2"])?])?)
            .next_key_digests(next_digests)
            .next_threshold(SigningThreshold::numeric(1))
            .prefix_derivation(PrefixDerivation::Blake3_256)
            .build()?,
        "multi_clause_weighted_inception" => InceptionBuilder::new(multisig)
            .signing_threshold(SigningThreshold::weighted(vec![
                weights(&["1/2", "1/2"])?,
                weights(&["1"])?,
            ])?)
            .next_key_digests(next_digests)
            .next_threshold(SigningThreshold::numeric(1))
            .prefix_derivation(PrefixDerivation::Blake3_256)
            .build()?,
        "witnessed_inception_default_toad" => InceptionBuilder::new(vec![transferable])
            .next_key_digests(vec![next_digest])
            .witnesses(witnesses)
            .prefix_derivation(PrefixDerivation::Blake3_256)
            .build()?,
        "witnessed_inception_integer_toad" => InceptionBuilder::new(vec![transferable])
            .next_key_digests(vec![next_digest])
            .witnesses(witnesses)
            .witness_threshold(2)
            .prefix_derivation(PrefixDerivation::Blake3_256)
            .threshold_encoding(ThresholdEncoding::Integer)
            .build()?,
        "configured_and_anchored_inception" => InceptionBuilder::new(vec![transferable])
            .next_key_digests(vec![next_digest])
            .configuration(vec![
                ConfigurationTrait::EstablishmentOnly,
                ConfigurationTrait::DoNotDelegate,
            ])
            .anchors(vec![seal(&[("i", &fixture.keys.transferable), ("s", "0")])?])
            .prefix_derivation(PrefixDerivation::Blake3_256)
            .build()?,
        "abandoned_inception" => InceptionBuilder::new(vec![transferable])
            .prefix_derivation(PrefixDerivation::Blake3_256)
            .build()?,
        "delegated_inception" => InceptionBuilder::new(vec![transferable])
            .next_key_digests(vec![next_digest])
            .delegator(root.identifier().clone())
            .build()?,
        "rotation" => rotation().build()?,
        "delegated_rotation" => rotation().kind(RotationKind::Delegated).build()?,
        "rotation_text_encoding" => rotation().threshold_encoding(ThresholdEncoding::Text).build()?,
        "rotation_high_sequence_number" => {
            RotationBuilder::new(root.identifier().clone(), root.said(), 255, vec![second])
                .next_key_digests(vec![next_digest])
                .signing_threshold(SigningThreshold::numeric(1))
                .next_threshold(SigningThreshold::numeric(1))
                .build()?
        }
        "rotation_with_witness_changes" => {
            let (first, rest) = witnesses.split_at(1);
            let (middle, last) = rest.split_at(1);
            rotation()
                .witnesses([first, middle].concat())
                .witness_cuts(first.to_vec())
                .witness_adds(last.to_vec())
                .build()?
        }
        "rotation_with_anchors" => {
            // The seal references the identifier's own inception event, as the fixture does.
            let root_identifier = root_identifier_qb64.clone();
            let root_said = root_said_qb64.clone();
            rotation()
                .anchors(vec![seal(&[("i", &root_identifier), ("s", "1"), ("d", &root_said)])?])
                .build()?
        }
        "interaction" => InteractionBuilder::new(root.identifier().clone(), root.said(), 1).build()?,
        "interaction_with_anchors" => {
            let root_identifier = root_identifier_qb64.clone();
            let root_said = root_said_qb64.clone();
            InteractionBuilder::new(root.identifier().clone(), root.said(), 2)
                .anchors(vec![seal(&[("i", &root_identifier), ("s", "0"), ("d", &root_said)])?])
                .build()?
        }
        _ => return Ok(None),
    };
    Ok(Some(event))
}

#[test]
fn fixture_metadata_matches_the_pinned_reference() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.schema_version, 1);
    assert_eq!(fixture.upstream, "https://github.com/WebOfTrust/signify-ts.git");
    assert_eq!(fixture.reference_sha, REFERENCE_SHA);
    assert_ne!(fixture.generated_on, "");
    assert_eq!(
        fixture.sources,
        ["src/keri/core/eventing.ts", "test/core/eventing.test.ts"]
    );
    Ok(())
}

#[test]
fn every_reference_event_is_reproduced_byte_for_byte() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.cases.len(), 20);
    let mut rebuilt = 0_usize;

    for case in &fixture.cases {
        // The recorded bytes must be internally consistent before anything is compared to them.
        let expected = decode_hex(&case.raw_hex)?;
        assert_eq!(expected, case.raw.as_bytes(), "case {} hex/text disagree", case.name);
        assert_eq!(expected.len(), case.raw_byte_size, "case {}", case.name);

        let Some(event) = build_case(&case.name, &fixture)? else {
            return Err(format!("fixture case {} has no Rust builder", case.name).into());
        };
        rebuilt += 1;

        assert_eq!(
            core::str::from_utf8(event.raw())?,
            case.raw,
            "case {} bytes differ",
            case.name
        );
        assert_eq!(event.kind().as_str(), case.event_kind, "case {}", case.name);
        assert_eq!(event.identifier().qb64()?, case.identifier, "case {}", case.name);
        assert_eq!(event.said().qb64()?, case.said, "case {}", case.name);
        assert_eq!(
            event.sad().get_text("s"),
            Some(case.sequence_number.as_str()),
            "case {}",
            case.name
        );
        assert_eq!(
            event.sad().get_text("v"),
            Some(case.version_string.as_str()),
            "case {}",
            case.name
        );
        // The declared size and the actual byte count always agree.
        assert_eq!(event.raw().len(), case.raw_byte_size, "case {}", case.name);
    }
    assert_eq!(rebuilt, fixture.cases.len());
    Ok(())
}

#[test]
fn the_witness_fault_tolerance_table_matches() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.ample_table.len(), 14);
    for row in &fixture.ample_table {
        assert_eq!(
            ample(row.witnesses, None, AmpleMode::Weak)?,
            row.weak,
            "n = {}",
            row.witnesses
        );
        assert_eq!(
            ample(row.witnesses, None, AmpleMode::Strong)?,
            row.strong,
            "n = {}",
            row.witnesses
        );
    }
    for row in &fixture.ample_explicit {
        assert_eq!(
            ample(row.witnesses, Some(row.faults), AmpleMode::Weak)?,
            row.weak,
            "n = {}, f = {}",
            row.witnesses,
            row.faults
        );
        assert_eq!(
            ample(row.witnesses, Some(row.faults), AmpleMode::Strong)?,
            row.strong,
            "n = {}, f = {}",
            row.witnesses,
            row.faults
        );
    }
    Ok(())
}

#[test]
#[expect(
    clippy::too_many_lines,
    reason = "one arm per recorded reference rejection; splitting the table would separate each \
              case from the fixture entry it maps to"
)]
fn reference_rejections_map_to_stable_rust_error_categories() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.rejected_cases.len(), 19);

    let transferable = VerificationKey::from_qb64(&fixture.keys.transferable)?;
    let non_transferable = VerificationKey::from_qb64(&fixture.keys.non_transferable)?;
    let second = VerificationKey::from_qb64(&fixture.keys.second)?;
    let next_digest = Digest::from_qb64(&fixture.keys.next_digest)?;
    let witnesses = prefixes(&fixture.keys.witnesses)?;
    let witness = witnesses.first().ok_or("fixture has no witnesses")?.clone();
    let other_witness = witnesses.get(1).ok_or("fixture has too few witnesses")?.clone();

    let root = InceptionBuilder::new(vec![transferable.clone()])
        .next_key_digests(vec![next_digest])
        .prefix_derivation(PrefixDerivation::Blake3_256)
        .build()?;
    let rotation = || {
        RotationBuilder::new(root.identifier().clone(), root.said(), 1, vec![second.clone()])
            .next_key_digests(vec![next_digest])
    };

    for case in &fixture.rejected_cases {
        assert!(!case.reference_error_category.is_empty(), "case {}", case.name);
        assert!(!case.reference_error_message.is_empty(), "case {}", case.name);

        let category = match case.name.as_str() {
            "signing_threshold_zero" => event_error_category(
                &InceptionBuilder::new(vec![transferable.clone()])
                    .signing_threshold(SigningThreshold::numeric(0))
                    .build()
                    .err()
                    .ok_or("accepted a zero signing threshold")?,
            ),
            "signing_threshold_exceeds_keys" => event_error_category(
                &InceptionBuilder::new(vec![transferable.clone()])
                    .signing_threshold(SigningThreshold::numeric(2))
                    .build()
                    .err()
                    .ok_or("accepted an unmeetable signing threshold")?,
            ),
            "duplicate_witnesses" => event_error_category(
                &InceptionBuilder::new(vec![transferable.clone()])
                    .witnesses(vec![witness.clone(), witness.clone()])
                    .build()
                    .err()
                    .ok_or("accepted duplicate witnesses")?,
            ),
            "witness_threshold_zero_with_witnesses" => event_error_category(
                &InceptionBuilder::new(vec![transferable.clone()])
                    .witnesses(vec![witness.clone()])
                    .witness_threshold(0)
                    .build()
                    .err()
                    .ok_or("accepted a zero witness threshold")?,
            ),
            "witness_threshold_exceeds_witnesses" => event_error_category(
                &InceptionBuilder::new(vec![transferable.clone()])
                    .witnesses(vec![witness.clone()])
                    .witness_threshold(2)
                    .build()
                    .err()
                    .ok_or("accepted an unmeetable witness threshold")?,
            ),
            "witness_threshold_without_witnesses" => event_error_category(
                &InceptionBuilder::new(vec![transferable.clone()])
                    .witness_threshold(1)
                    .build()
                    .err()
                    .ok_or("accepted a witness threshold with no witnesses")?,
            ),
            "non_transferable_prefix_with_next_keys" => event_error_category(
                &InceptionBuilder::new(vec![non_transferable.clone()])
                    .next_key_digests(vec![next_digest])
                    .prefix_derivation(PrefixDerivation::Ed25519NonTransferable)
                    .build()
                    .err()
                    .ok_or("accepted next keys for a non-transferable identifier")?,
            ),
            "non_transferable_prefix_with_witnesses" => event_error_category(
                &InceptionBuilder::new(vec![non_transferable.clone()])
                    .witnesses(vec![witness.clone()])
                    .witness_threshold(1)
                    .prefix_derivation(PrefixDerivation::Ed25519NonTransferable)
                    .build()
                    .err()
                    .ok_or("accepted witnesses for a non-transferable identifier")?,
            ),
            "non_transferable_prefix_with_anchors" => event_error_category(
                &InceptionBuilder::new(vec![non_transferable.clone()])
                    .anchors(vec![seal(&[("i", "ABCDE")])?])
                    .prefix_derivation(PrefixDerivation::Ed25519NonTransferable)
                    .build()
                    .err()
                    .ok_or("accepted anchors for a non-transferable identifier")?,
            ),
            "delegated_inception_with_basic_prefix" => event_error_category(
                &InceptionBuilder::new(vec![transferable.clone()])
                    .next_key_digests(vec![next_digest])
                    .delegator(root.identifier().clone())
                    .prefix_derivation(PrefixDerivation::Ed25519)
                    .build()
                    .err()
                    .ok_or("accepted a basic prefix for a delegated identifier")?,
            ),
            "rotation_sequence_number_zero" => event_error_category(
                &RotationBuilder::new(root.identifier().clone(), root.said(), 0, vec![second.clone()])
                    .next_key_digests(vec![next_digest])
                    .build()
                    .err()
                    .ok_or("accepted sequence number zero for a rotation")?,
            ),
            "rotation_non_rotation_ilk" => {
                // `RotationKind` names only `rot` and `drt`, so an inception ilk cannot be asked
                // for at all; the reference validates it at run time.
                assert!(case.reference_error_message.contains("Invalid ilk"));
                case.rust_error_category.as_str()
            }
            "rotation_duplicate_cuts" => event_error_category(
                &rotation()
                    .witness_cuts(vec![witness.clone(), witness.clone()])
                    .build()
                    .err()
                    .ok_or("accepted duplicate witness cuts")?,
            ),
            "rotation_duplicate_adds" => event_error_category(
                &rotation()
                    .witness_adds(vec![witness.clone(), witness.clone()])
                    .build()
                    .err()
                    .ok_or("accepted duplicate witness additions")?,
            ),
            "rotation_witness_added_twice" => event_error_category(
                &rotation()
                    .witnesses(vec![witness.clone()])
                    .witness_adds(vec![witness.clone()])
                    .build()
                    .err()
                    .ok_or("accepted adding a witness that is already in effect")?,
            ),
            "rotation_witness_cut_and_added" => event_error_category(
                &rotation()
                    .witnesses(vec![witness.clone()])
                    .witness_cuts(vec![witness.clone()])
                    .witness_adds(vec![witness.clone()])
                    .build()
                    .err()
                    .ok_or("accepted cutting and adding the same witness")?,
            ),
            "rotation_cut_not_a_witness" => event_error_category(
                &rotation()
                    .witnesses(vec![witness.clone()])
                    .witness_cuts(vec![other_witness.clone()])
                    .build()
                    .err()
                    .ok_or("accepted cutting a witness that is not in effect")?,
            ),
            "interaction_sequence_number_zero" => event_error_category(
                &InteractionBuilder::new(root.identifier().clone(), root.said(), 0)
                    .build()
                    .err()
                    .ok_or("accepted sequence number zero for an interaction")?,
            ),
            "ample_impossible_fault_count" => event_error_category(
                &ample(4, Some(2), AmpleMode::Weak)
                    .err()
                    .ok_or("accepted f = 2 for n = 4")?,
            ),
            other => return Err(format!("unmapped rejected case {other}").into()),
        };
        assert_eq!(category, case.rust_error_category, "case {}", case.name);
    }
    Ok(())
}

#[test]
#[expect(
    clippy::too_many_lines,
    reason = "one block per pinned reference defect; each block states the recorded upstream \
              behavior next to the Rust behavior that replaces it, and separating them would \
              lose that pairing"
)]
fn reference_quirks_are_pinned_and_safely_diverged() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let quirks = &fixture.reference_quirks;

    let transferable = VerificationKey::from_qb64(&fixture.keys.transferable)?;
    let non_transferable = VerificationKey::from_qb64(&fixture.keys.non_transferable)?;
    let second = VerificationKey::from_qb64(&fixture.keys.second)?;
    let next_digest = Digest::from_qb64(&fixture.keys.next_digest)?;
    let multisig = keys(&fixture.keys.multisig)?;
    let next_digests = digests(&fixture.keys.next_digests)?;
    let root = InceptionBuilder::new(vec![transferable.clone()])
        .next_key_digests(vec![next_digest])
        .prefix_derivation(PrefixDerivation::Blake3_256)
        .build()?;

    // 1. Multi-key inception is unreachable in the reference without an explicit code.
    let multi = &quirks.multi_key_inception_needs_an_explicit_code;
    assert_eq!(multi.reference_error_category, "Error");
    assert!(multi.reference_error_message.contains("Empty Material"));
    assert_ne!(multi.note, "");
    assert_ne!(multi.rust_decision, "");
    // Rust builds it, and builds exactly the event the reference produces with an explicit code.
    let inferred = InceptionBuilder::new(multisig.clone())
        .signing_threshold(SigningThreshold::numeric(2))
        .next_key_digests(next_digests.clone())
        .next_threshold(SigningThreshold::numeric(1))
        .build()?;
    let equivalent = fixture
        .cases
        .iter()
        .find(|case| case.name == multi.rust_equivalent_case)
        .ok_or("fixture names no equivalent case")?;
    assert_eq!(core::str::from_utf8(inferred.raw())?, equivalent.raw);

    // 2. The next-threshold encoding follows the *current* threshold. Reproduced exactly.
    let encoding = &quirks.next_threshold_encoding_follows_the_current_threshold;
    assert_eq!(
        encoding.weighted_current_numeric_next_integer_encoding.nt_type,
        "string"
    );
    assert_eq!(encoding.weighted_current_numeric_next_integer_encoding.nt, "1");
    assert_ne!(encoding.note, "");
    assert!(encoding.rust_decision.contains("reproduced"));
    let weighted_current = InceptionBuilder::new(multisig.clone())
        .signing_threshold(SigningThreshold::weighted(vec![weights(&["1/2", "1/2", "1/2"])?])?)
        .next_key_digests(next_digests.clone())
        .next_threshold(SigningThreshold::numeric(1))
        .prefix_derivation(PrefixDerivation::Blake3_256)
        .threshold_encoding(ThresholdEncoding::Integer)
        .build()?;
    assert_eq!(
        core::str::from_utf8(weighted_current.raw())?,
        encoding.weighted_current_numeric_next_integer_encoding.raw,
        "the integer-encoding quirk must be reproduced byte for byte"
    );

    // 3. The mirror case makes the reference drop the field entirely. Rust refuses.
    let dropped = &quirks.numeric_current_weighted_next_drops_the_field;
    assert!(
        !dropped.contains_next_threshold,
        "the reference event must be missing its next-threshold field"
    );
    assert!(!dropped.raw.contains(r#""nt""#));
    assert_ne!(dropped.note, "");
    let error = InceptionBuilder::new(multisig.clone())
        .signing_threshold(SigningThreshold::numeric(2))
        .next_key_digests(next_digests.clone())
        .next_threshold(SigningThreshold::weighted(vec![weights(&["1/2", "1/2"])?])?)
        .prefix_derivation(PrefixDerivation::Blake3_256)
        .threshold_encoding(ThresholdEncoding::Integer)
        .build()
        .err()
        .ok_or("built an event with no next-threshold field")?;
    assert_eq!(event_error_category(&error), dropped.rust_error_category);

    // 4. The next threshold is validated against the current key count.
    let validation = &quirks.next_threshold_validated_against_the_current_key_count;
    assert!(validation.reference_error_message.contains("Invalid nsith"));
    assert_ne!(validation.note, "");
    assert_ne!(validation.rust_decision, "");
    assert_ne!(validation.unsatisfiable_note, "");
    // Rust builds the commitment the reference rejects...
    InceptionBuilder::new(vec![transferable.clone()])
        .next_key_digests(next_digests.clone())
        .next_threshold(SigningThreshold::numeric(2))
        .prefix_derivation(PrefixDerivation::Blake3_256)
        .build()?;
    // ...and rejects the unsatisfiable one it accepts.
    assert_eq!(validation.unsatisfiable_accepted.nt, "2");
    assert!(
        validation.unsatisfiable_accepted.raw.contains(r#""nt":"2","n":[]"#),
        "the reference event must commit to a 2-of-nothing rotation"
    );
    let error = InceptionBuilder::new(multisig)
        .signing_threshold(SigningThreshold::numeric(2))
        .next_threshold(SigningThreshold::numeric(2))
        .prefix_derivation(PrefixDerivation::Blake3_256)
        .build()
        .err()
        .ok_or("accepted a next threshold no digest set can satisfy")?;
    assert_eq!(event_error_category(&error), "NextThresholdExceedsDigests");

    // 5. An inferred basic prefix skips its own emptiness checks.
    let auto = &quirks.auto_selected_basic_prefix_skips_its_own_checks;
    assert!(auto.non_transferable_with_next_keys.contains(r#""i":"B"#));
    assert!(auto.non_transferable_with_next_keys.contains(r#""n":["E"#));
    assert!(auto.non_transferable_with_anchors.contains(r#""a":[{"#));
    assert_ne!(auto.note, "");
    assert_ne!(auto.rust_decision, "");
    for builder in [
        InceptionBuilder::new(vec![non_transferable.clone()]).next_key_digests(vec![next_digest]),
        InceptionBuilder::new(vec![non_transferable]).anchors(vec![seal(&[("i", "x")])?]),
    ] {
        let error = builder
            .build()
            .err()
            .ok_or("built a non-transferable identifier that commits to a future")?;
        assert_eq!(event_error_category(&error), auto.rust_error_category);
    }

    // 6. Rotation cannot abandon an identifier in the reference.
    let abandon = &quirks.rotation_cannot_abandon_an_identifier;
    assert!(
        abandon
            .default_next_threshold
            .reference_error_message
            .contains("Signing threshold failure")
    );
    assert!(abandon.explicit_zero.reference_error_message.contains("less than 1"));
    assert_ne!(abandon.note, "");
    assert_ne!(abandon.rust_decision, "");
    let abandoning = RotationBuilder::new(root.identifier().clone(), root.said(), 1, vec![second.clone()]).build()?;
    assert_eq!(abandoning.sad().get_text("nt"), Some("0"));
    assert_eq!(abandoning.sad().get("n").and_then(SadValue::as_array), Some(&[][..]));

    // 7. Rotation silently ignores configuration traits; Rust has no such setter.
    let configuration = &quirks.rotation_ignores_the_configuration_argument;
    assert!(!configuration.fields.contains(",c,"));
    assert_ne!(configuration.note, "");
    assert_ne!(configuration.rust_decision, "");
    let rotation = RotationBuilder::new(root.identifier().clone(), root.said(), 1, vec![second.clone()])
        .next_key_digests(vec![next_digest])
        .build()?;
    assert!(!rotation.sad().contains("c"));
    let labels: Vec<&str> = rotation.sad().entries().map(|(label, _)| label).collect();
    assert_eq!(labels.join(","), configuration.fields);

    // 8. An absent identifier or prior digest simply drops the field.
    let omitted = &quirks.rotation_omits_absent_identifier_and_prior;
    assert!(!omitted.missing_identifier.contains(r#""i":"#));
    assert!(!omitted.missing_prior.contains(r#""p":"#));
    assert_ne!(omitted.note, "");
    assert_ne!(omitted.rust_decision, "");
    // Both are required constructor arguments in Rust, so every rotation carries them.
    assert!(rotation.sad().contains("i"));
    assert!(rotation.sad().contains("p"));
    Ok(())
}
